const outputRoot=path.resolve(root,'../outputs/development-stages/main-parallel-p4/runtime');
const imageTag='public.ecr.aws/supabase/postgres:17.11.0.018';
const imageId='sha256:7c31363a3f7434ff14945f1b8a4880e6eca8b362e197e88b87c476c77aa3cf8c';
