    const initial=parseOneJson(resource.ownerSql("select json_build_object('present',to_regnamespace('collector_private') is not null,'foreign',exists(select 1 from pg_namespace where nspname not like 'pg_%' and nspname not in ('information_schema','public','collector_private','collector_api')));"));
